"""Background music for the demo video, generated by Lyria 3.5 (Gemini API) from a text prompt. Writes demo/music_lyria.mp3."""
import sys, os, base64, json, time
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), '..'))
from agent import gemini
gemini._load_env()
c = gemini._client()
P = ("Instrumental background music for a 60-second tech product video about 3D billboard ads in a city at night. "
     "Modern, warm and confident: soft electronic pulse, airy synth pads, light percussion that builds gently, uplifting and premium, "
     "like an Apple or Google product film. No vocals. Even level, suitable under voice-over.")
for model in ['lyria-3.5', 'lyria-3-clip-preview']:
    try:
        t = time.time(); it = c.interactions.create(model=model, input=P)
        print(model, 'ok', round(time.time()-t,1), [a for a in dir(it) if 'output' in a])
        for name in ['output_audio', 'output_audios', 'outputs']:
            v = getattr(it, name, None)
            if v is not None: print(name, type(v), str(v)[:300])
        oa = getattr(it, 'output_audio', None)
        if oa is not None:
            data = base64.b64decode(oa.data) if isinstance(oa.data, str) else oa.data
            ext = 'mp3' if 'mp3' in str(getattr(oa, 'mime_type', '')) or 'mpeg' in str(getattr(oa, 'mime_type', '')) else 'wav'
            open(f'/Users/sivasuryachandran/Documents/HCK/Tangle/demo/music_lyria.mp3', 'wb').write(data); print('saved', model, ext, len(data), getattr(oa, 'mime_type', ''))
            gemini._log({"tag": "demo_music", "model": model, "settings": {}, "seconds": round(time.time()-t, 2), "usage": gemini._usage(it)})
            break
    except Exception as e:
        print(model, 'ERR', str(e)[:300])
